create table public.site_faqs (
  id uuid primary key default gen_random_uuid(),
  category text not null check(length(btrim(category)) between 2 and 80 and category !~ '[[:cntrl:]]' and lower(btrim(category))<>'all categories'),
  question text not null check(length(btrim(question)) between 5 and 250 and question !~ '[[:cntrl:]]'),
  answer text not null check(length(btrim(answer)) between 10 and 8000),
  sort_order integer not null default 0 check(sort_order between 0 and 10000),
  status text not null default 'draft' check(status in ('draft','published')),
  version integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index site_faqs_unique_question on public.site_faqs(lower(btrim(category)),lower(btrim(question)));
create index site_faqs_public_order on public.site_faqs(sort_order,id) where status='published';
alter table public.site_faqs enable row level security;
revoke all on public.site_faqs from public,anon,authenticated;
grant select on public.site_faqs to anon,authenticated;
grant insert,update,delete on public.site_faqs to authenticated;
create policy "Published FAQs are public" on public.site_faqs for select to anon,authenticated using(status='published');
create policy "Admins manage FAQs" on public.site_faqs for all to authenticated
  using((select private.is_platform_admin())) with check((select private.is_platform_admin()));
create trigger site_faq_version before update on public.site_faqs for each row execute function private.version_site_record();

-- The existing question set is inserted below. Future edits belong in admin management, not this seed.

insert into public.site_faqs(category,question,answer,sort_order,status)
select category,question,answer,sort_order,status from jsonb_to_recordset($faq_seed$[{"category":"Getting Started","question":"How do I create an account?","answer":"Choose Sign Up, enter your contact details and location, then follow the confirmation email. Google sign-in is also available when configured.","sort_order":10,"status":"published"},{"category":"Getting Started","question":"Is there a cost to create an account?","answer":"Creating an account is free. Review the tutor's rate and any applicable plan or booking terms before agreeing to a paid service.","sort_order":20,"status":"published"},{"category":"Getting Started","question":"What information do I need to sign up?","answer":"Registration asks for your name, email, phone and location. Applicants who want to teach complete a separate tutor application with experience, qualifications and required documents.","sort_order":30,"status":"published"},{"category":"Finding a Tutor","question":"How do I know if a tutor is qualified?","answer":"View the tutor's qualifications, subjects and experience on their profile. Tutor applications are reviewed before approval. Ask the team about the checks performed; approval is not a guarantee of results or a claim that criminal background screening has been completed.","sort_order":40,"status":"published"},{"category":"Finding a Tutor","question":"Can I change tutors if I'm not satisfied?","answer":"You can search for another tutor and contact the team for help. Existing lesson cancellation or refund terms still apply; changing tutors does not automatically cancel a booking.","sort_order":50,"status":"published"},{"category":"Finding a Tutor","question":"What subjects and grade levels do you cover?","answer":"Browse the subject catalogue from primary school to university level. If your subject or university module is missing, submit a subject request so the team can explore available support.","sort_order":60,"status":"published"},{"category":"Finding a Tutor","question":"How do I search for tutors in my area?","answer":"Type and select your city or suburb, then use the distance and lesson-format filters. Nearby tutors are shown using available location information. You can also choose tutors farther than 25 km or an online lesson format.","sort_order":70,"status":"published"},{"category":"Booking & Payments","question":"How are payments handled?","answer":"Some payment records and plan options currently use demonstration data. A demo payment does not charge you. Before any real purchase, review the total price, payment method and service terms provided for that booking or plan.","sort_order":80,"status":"published"},{"category":"Booking & Payments","question":"Can I schedule sessions outside of regular hours?","answer":"Yes! Many tutors offer flexible scheduling including evenings and weekends. You can filter tutors by availability to find ones that match your schedule.","sort_order":90,"status":"published"},{"category":"Booking & Payments","question":"What happens if I need to cancel a session?","answer":"Review the cancellation and rescheduling terms provided before confirming a lesson. Contact support with your booking reference if you need help. Applicable consumer rights remain available; the site does not promise an automatic 24-hour refund for every booking.","sort_order":100,"status":"published"},{"category":"Booking & Payments","question":"Are there any hidden fees?","answer":"Review the total price and any additional charges disclosed before agreeing to pay. If a price or fee is unclear, contact the team before completing the purchase.","sort_order":110,"status":"published"},{"category":"For Tutors","question":"How do I become a tutor on your platform?","answer":"Click 'Become a Tutor', complete your profile, submit your qualifications for verification, and once approved, you can start accepting students.","sort_order":120,"status":"published"},{"category":"For Tutors","question":"What are the requirements to become a tutor?","answer":"Complete all application stages, provide your teaching details and upload your ID and qualification documents. The team reviews the application and may request clarification before approval.","sort_order":130,"status":"published"},{"category":"For Tutors","question":"How much can I earn as a tutor?","answer":"Tutors specify an hourly rate in their application and profile. Actual earnings depend on agreed rates and completed work; the platform does not guarantee a minimum income or number of students.","sort_order":140,"status":"published"},{"category":"For Tutors","question":"How do I get paid?","answer":"Confirm the payment and payout arrangements with the team before delivering a paid lesson. Demonstration earnings and payment records do not represent a real bank transfer or an automated weekly payout service.","sort_order":150,"status":"published"},{"category":"Technical Support","question":"What if I have technical issues during an online session?","answer":"Contact our support team through the contact form or the support options in your dashboard. Responses are handled during the support hours listed on our contact page.","sort_order":160,"status":"published"},{"category":"Technical Support","question":"What equipment do I need for online tutoring?","answer":"Agree the online meeting method with your tutor. A suitable device, microphone and stable internet connection are normally needed; check whether a webcam or other software is required for your lesson.","sort_order":170,"status":"published"},{"category":"Technical Support","question":"Is my personal information secure?","answer":"The app uses protected account roles, database access rules and private application-document storage. No online service is risk free. Read the Privacy Policy for data use, providers and your rights; never share passwords or payment card details in enquiries.","sort_order":180,"status":"published"},{"category":"Safety & Trust","question":"How do you verify tutor backgrounds?","answer":"Applicants provide identity and qualification documents for admin review. Ask the team about any additional checks relevant to your tutor. The platform does not represent application approval as completed criminal background screening.","sort_order":190,"status":"published"},{"category":"Safety & Trust","question":"What safety measures are in place for in-person sessions?","answer":"Agree a suitable safe meeting location and supervision arrangements in advance. A parent or legally authorised guardian must arrange and supervise use by a minor. Report concerns to the team; use emergency services for immediate danger.","sort_order":200,"status":"published"},{"category":"Safety & Trust","question":"How does the review system work?","answer":"Published student reviews are linked to completed bookings. Top rated status requires a qualifying rating, enough reviews from different students, completed sessions and time on the platform; one review is not enough. Featured promotion is a separate label.","sort_order":210,"status":"published"}]$faq_seed$::jsonb) as seed(category text,question text,answer text,sort_order integer,status text);
notify pgrst,'reload schema';
